import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

/* ================================================================
   EARTH DIGITAL TWIN
   Radius 1.0 in scene units = 6371 km.
   The globe mesh is fixed in space (textures = geography); the sun
   direction is computed from the simulation clock, so the day/night
   terminator sweeps across the surface exactly as it does in reality.
   ================================================================ */

const EARTH_RADIUS_KM = 6371;
const DEG = Math.PI / 180;

/* ---------------- astronomy ---------------- */

function toJulian(ms) { return ms / 86400000 + 2440587.5; }

// Subsolar point (the lat/lon where the sun is at zenith) for a given time.
// Low-precision solar ephemeris (Meeus), good to ~0.01 degrees.
function subsolarPoint(ms) {
  const n = toJulian(ms) - 2451545.0;
  const L = (280.460 + 0.9856474 * n) % 360;
  const g = ((357.528 + 0.9856003 * n) % 360) * DEG;
  const lambda = (L + 1.915 * Math.sin(g) + 0.020 * Math.sin(2 * g)) * DEG;
  const eps = (23.439 - 0.0000004 * n) * DEG;
  const decl = Math.asin(Math.sin(eps) * Math.sin(lambda));
  const ra = Math.atan2(Math.cos(eps) * Math.sin(lambda), Math.cos(lambda));
  const gmst = (280.46061837 + 360.98564736629 * n) % 360;
  let lon = (ra / DEG - gmst) % 360;
  if (lon < -180) lon += 360;
  if (lon > 180) lon -= 360;
  return { lat: decl / DEG, lon };
}

/* ---------------- geo <-> scene mapping ---------------- */

function latLonToVector3(lat, lon, r = 1) {
  const phi = (90 - lat) * DEG;
  const theta = (lon + 180) * DEG;
  return new THREE.Vector3(
    -r * Math.sin(phi) * Math.cos(theta),
    r * Math.cos(phi),
    r * Math.sin(phi) * Math.sin(theta)
  );
}

function vector3ToLatLon(p) {
  const r = p.length();
  const lat = 90 - Math.acos(p.y / r) / DEG;
  let lon = Math.atan2(p.z, -p.x) / DEG - 180;
  if (lon < -180) lon += 360;
  return { lat, lon };
}

function fmtLatLon(lat, lon) {
  const ns = lat >= 0 ? 'N' : 'S';
  const ew = lon >= 0 ? 'E' : 'W';
  return `${Math.abs(lat).toFixed(3)}° ${ns}, ${Math.abs(lon).toFixed(3)}° ${ew}`;
}

/* ---------------- loading ---------------- */

const manager = new THREE.LoadingManager();
const loadingEl = document.getElementById('loading');
const fillEl = document.getElementById('loading-fill');
manager.onProgress = (_url, loaded, total) => {
  fillEl.style.width = `${Math.round((loaded / total) * 100)}%`;
};
manager.onLoad = () => {
  loadingEl.classList.add('done');
  setTimeout(() => loadingEl.remove(), 900);
};

const texLoader = new THREE.TextureLoader(manager);
function loadTex(url, srgb = true) {
  const t = texLoader.load(url);
  t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  return t;
}

const dayMap = loadTex('textures/8k_earth_daymap.jpg');
const nightMap = loadTex('textures/8k_earth_nightmap.jpg');
const cloudMap = loadTex('textures/8k_earth_clouds.jpg');
const starMap = loadTex('textures/8k_stars_milky_way.jpg');
const normalMap = loadTex('textures/earth_normal_2048.jpg', false);
const specularMap = loadTex('textures/earth_specular_2048.jpg', false);

/* ---------------- renderer / scene ---------------- */

const canvas = document.getElementById('scene');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;

const maxAniso = renderer.capabilities.getMaxAnisotropy();
for (const t of [dayMap, nightMap, cloudMap, normalMap, specularMap]) {
  t.anisotropy = maxAniso;
}

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.005, 200);
camera.position.set(-1.9, 1.1, 2.1);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.minDistance = 1.07;
controls.maxDistance = 9;
controls.enablePan = false;

/* ---------------- globe ---------------- */

const sunDirection = new THREE.Vector3(1, 0, 0);

const globeUniforms = {
  dayMap: { value: dayMap },
  nightMap: { value: nightMap },
  normalMap: { value: normalMap },
  specularMap: { value: specularMap },
  sunDirection: { value: sunDirection },
  nightIntensity: { value: 1.0 },
  normalScale: { value: 1.6 },
};

const globeMaterial = new THREE.ShaderMaterial({
  uniforms: globeUniforms,
  vertexShader: /* glsl */`
    varying vec2 vUv;
    varying vec3 vNormalW;
    varying vec3 vPosW;
    void main() {
      vUv = uv;
      vNormalW = normalize(mat3(modelMatrix) * normal);
      vec4 wp = modelMatrix * vec4(position, 1.0);
      vPosW = wp.xyz;
      gl_Position = projectionMatrix * viewMatrix * wp;
    }
  `,
  fragmentShader: /* glsl */`
    uniform sampler2D dayMap;
    uniform sampler2D nightMap;
    uniform sampler2D normalMap;
    uniform sampler2D specularMap;
    uniform vec3 sunDirection;
    uniform float nightIntensity;
    uniform float normalScale;
    varying vec2 vUv;
    varying vec3 vNormalW;
    varying vec3 vPosW;

    void main() {
      vec3 nGeom = normalize(vNormalW);

      // tangent frame for an equirectangular-mapped sphere
      vec3 T = normalize(cross(vec3(0.0, 1.0, 0.0), nGeom));
      vec3 B = normalize(cross(nGeom, T));
      vec3 mapN = texture2D(normalMap, vUv).xyz * 2.0 - 1.0;
      mapN.xy *= normalScale;
      vec3 N = normalize(T * mapN.x + B * mapN.y + nGeom * mapN.z);

      vec3 viewDir = normalize(cameraPosition - vPosW);
      float sunDot = dot(nGeom, sunDirection);
      float dayFactor = smoothstep(-0.15, 0.12, sunDot);

      vec3 dayColor = texture2D(dayMap, vUv).rgb;

      // sunlight reddens near the terminator
      vec3 sunTint = mix(vec3(1.0, 0.45, 0.22), vec3(1.0, 0.98, 0.94), smoothstep(0.0, 0.3, sunDot));
      float diff = clamp(dot(N, sunDirection) * 1.05 + 0.05, 0.0, 1.0);
      vec3 lit = dayColor * diff * sunTint;

      // ocean sun glint
      float specMask = texture2D(specularMap, vUv).r;
      vec3 H = normalize(sunDirection + viewDir);
      float spec = pow(max(dot(N, H), 0.0), 90.0) * specMask;
      lit += spec * sunTint * 0.8 * smoothstep(0.0, 0.12, sunDot);

      // city lights emerge as the terminator passes
      vec3 nightColor = pow(texture2D(nightMap, vUv).rgb, vec3(1.1)) * 2.4;
      vec3 night = nightColor * (1.0 - dayFactor) * nightIntensity;
      night += dayColor * 0.015 * (1.0 - dayFactor); // faint earthshine

      // in-scattering rim on the lit side
      float fres = pow(1.0 - max(dot(viewDir, nGeom), 0.0), 2.6);
      vec3 atmo = vec3(0.35, 0.58, 1.0) * fres * 0.6 * smoothstep(-0.12, 0.4, sunDot);

      gl_FragColor = vec4(lit + night + atmo, 1.0);
      #include <tonemapping_fragment>
      #include <colorspace_fragment>
    }
  `,
});

const globe = new THREE.Mesh(new THREE.SphereGeometry(1, 160, 160), globeMaterial);
scene.add(globe);

/* ---------------- clouds ---------------- */

const cloudUniforms = {
  map: { value: cloudMap },
  sunDirection: { value: sunDirection },
  opacity: { value: 0.95 },
};

const clouds = new THREE.Mesh(
  new THREE.SphereGeometry(1.0045, 120, 120),
  new THREE.ShaderMaterial({
    uniforms: cloudUniforms,
    transparent: true,
    depthWrite: false,
    vertexShader: /* glsl */`
      varying vec2 vUv;
      varying vec3 vNormalW;
      void main() {
        vUv = uv;
        vNormalW = normalize(mat3(modelMatrix) * normal);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: /* glsl */`
      uniform sampler2D map;
      uniform vec3 sunDirection;
      uniform float opacity;
      varying vec2 vUv;
      varying vec3 vNormalW;
      void main() {
        vec3 n = normalize(vNormalW);
        float a = texture2D(map, vUv).r * opacity;
        float l = clamp(dot(n, sunDirection) * 1.15 + 0.06, 0.0, 1.0);
        vec3 col = vec3(1.0) * l + vec3(0.06, 0.08, 0.14) * (1.0 - l) * 0.35;
        gl_FragColor = vec4(col, a);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
    `,
  })
);
