let issTimer = null;
let issTarget = null;   // Vector3 the marker eases toward
let issTrailCount = 0;
const hudIssRow = document.getElementById('hud-iss-row');
const hudIss = document.getElementById('hud-iss');

async function pollISS() {
  try {
    const res = await fetch('https://api.wheretheiss.at/v1/satellites/25544');
    if (!res.ok) throw new Error(res.status);
    const d = await res.json();
    const r = 1 + d.altitude / EARTH_RADIUS_KM;
    issTarget = latLonToVector3(d.latitude, d.longitude, r);
    if (!issGroup.visible || issGroup.position.lengthSq() < 0.5) {
      issGroup.position.copy(issTarget); // first fix: jump, don't ease
    }
    hudIss.textContent = `${fmtLatLon(d.latitude, d.longitude)} · ${Math.round(d.altitude)} km · ${(d.velocity).toFixed(0)} km/h`;
    // trail
    const attr = issTrailGeo.getAttribute('position');
    if (issTrailCount < issTrailMax) {
      issTarget.toArray(attr.array, issTrailCount * 3);
      issTrailCount++;
    } else {
      attr.array.copyWithin(0, 3);
      issTarget.toArray(attr.array, (issTrailMax - 1) * 3);
    }
    issTrailGeo.setDrawRange(0, issTrailCount);
    attr.needsUpdate = true;
  } catch {
    hudIss.textContent = 'signal lost — retrying…';
  }
}

function setISSEnabled(on) {
  issGroup.visible = on;
  issTrail.visible = on;
  hudIssRow.classList.toggle('hidden', !on);
  if (on) {
    hudIss.textContent = 'acquiring…';
    pollISS();
    issTimer = setInterval(pollISS, 5000);
  } else {
    clearInterval(issTimer);
    issTimer = null;
    issTarget = null;
    issTrailCount = 0;
    issTrailGeo.setDrawRange(0, 0);
  }
}

/* ---------------- simulation clock ---------------- */

const SPEEDS = [-86400, -14400, -3600, -600, -60, 1, 60, 600, 3600, 14400, 86400];
let speedIdx = SPEEDS.indexOf(1);
let paused = false;
let simTime = Date.now();

const simClockEl = document.getElementById('sim-clock');
const speedEl = document.getElementById('t-speed');
const hudSun = document.getElementById('hud-sun');

function fmtSpeed(s) {
  const a = Math.abs(s);
  const sign = s < 0 ? '−' : '';
  if (a >= 86400) return `${sign}${a / 86400} d/s`;
  if (a >= 3600) return `${sign}${a / 3600} h/s`;
  if (a >= 60) return `${sign}${a / 60} min/s`;
  return `${sign}${a}×`;
}

function updateSpeedUI() {
  speedEl.textContent = paused ? 'paused' : fmtSpeed(SPEEDS[speedIdx]);
  document.getElementById('t-pause').textContent = paused ? '▶' : '⏸';
}

document.getElementById('t-faster').onclick = () => { speedIdx = Math.min(speedIdx + 1, SPEEDS.length - 1); paused = false; updateSpeedUI(); };
document.getElementById('t-slower').onclick = () => { speedIdx = Math.max(speedIdx - 1, 0); paused = false; updateSpeedUI(); };
document.getElementById('t-pause').onclick = () => { paused = !paused; updateSpeedUI(); };
document.getElementById('t-now').onclick = () => { simTime = Date.now(); speedIdx = SPEEDS.indexOf(1); paused = false; updateSpeedUI(); };
updateSpeedUI();

function fmtClock(ms) {
  const d = new Date(ms);
  const p = (v, n = 2) => String(v).padStart(n, '0');
  return `${d.getUTCFullYear()}-${p(d.getUTCMonth() + 1)}-${p(d.getUTCDate())} ` +
         `${p(d.getUTCHours())}:${p(d.getUTCMinutes())}:${p(d.getUTCSeconds())} UTC`;
}

