searchInput.addEventListener('input', () => {
  clearTimeout(searchTimer);
  const q = searchInput.value.trim();
  if (q.length < 3) { resultsEl.classList.remove('open'); return; }
  searchTimer = setTimeout(() => runSearch(q), 350);
});
searchInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    const first = resultsEl.querySelector('.result-item');
    if (first) first.click();
  }
  if (e.key === 'Escape') resultsEl.classList.remove('open');
});
document.addEventListener('pointerdown', (e) => {
  if (!e.target.closest('#search-box')) resultsEl.classList.remove('open');
});

async function runSearch(q) {
  try {
    const res = await fetch(
      `https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(q)}&format=json&limit=5&accept-language=en`
    );
    const items = await res.json();
    resultsEl.innerHTML = '';
    if (!items.length) {
      resultsEl.innerHTML = '<div class="result-item">No results</div>';
    }
    for (const it of items) {
      const div = document.createElement('div');
      div.className = 'result-item';
      const name = it.display_name.split(',')[0];
      div.innerHTML = `${name}<small>${it.display_name}</small>`;
      div.onclick = () => {
        resultsEl.classList.remove('open');
        searchInput.value = name;
        const lat = parseFloat(it.lat), lon = parseFloat(it.lon);
        flyTo(lat, lon, 1.45);
        inspectLocation(lat, lon);
      };
      resultsEl.appendChild(div);
    }
    resultsEl.classList.add('open');
  } catch { /* offline: search silently unavailable */ }
}

/* ---------------- fly-to animation ---------------- */

let flight = null;

function flyTo(lat, lon, dist = 1.8) {
  const startDir = camera.position.clone().normalize();
  const endDir = latLonToVector3(lat, lon, 1).normalize();
  const q = new THREE.Quaternion().setFromUnitVectors(startDir, endDir);
  flight = {
    t: 0,
    duration: 1.7,
    startDir,
    q,
    startDist: camera.position.length(),
    endDist: dist,
  };
}

function stepFlight(dt) {
  if (!flight) return;
  flight.t += dt / flight.duration;
  const e = flight.t >= 1 ? 1 : 1 - Math.pow(1 - flight.t, 3); // ease-out cubic
  const q = new THREE.Quaternion().slerp(flight.q, e);
  const dist = THREE.MathUtils.lerp(flight.startDist, flight.endDist, e);
  camera.position.copy(flight.startDir).applyQuaternion(q).multiplyScalar(dist);
  if (flight.t >= 1) flight = null;
}

renderer.domElement.addEventListener('pointerdown', () => { flight = null; });

