/* ---------------- main loop ---------------- */

const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.1);

  // advance simulation time
  if (!paused) simTime += dt * 1000 * SPEEDS[speedIdx];
  simClockEl.textContent = fmtClock(simTime);

  // sun position drives the terminator
  const sp = subsolarPoint(simTime);
  sunDirection.copy(latLonToVector3(sp.lat, sp.lon, 1)).normalize();
  sunSprite.position.copy(sunDirection).multiplyScalar(70);
  hudSun.textContent = fmtLatLon(sp.lat, sp.lon);

  // clouds drift slowly relative to the surface (visible at high time speeds)
  if (!paused) clouds.rotation.y += (dt * SPEEDS[speedIdx]) * (Math.PI * 2 / (86400 * 18));

  // marker pulse
  if (marker.visible) {
    const s = 0.05 + Math.sin(performance.now() * 0.004) * 0.012;
    markerGlow.scale.setScalar(s);
  }

  // ISS easing toward latest fix
  if (issGroup.visible && issTarget) {
    issGroup.position.lerp(issTarget, Math.min(dt * 2.5, 1));
  }

  // distance-adaptive navigation feel + HUD altitude
  const d = camera.position.length() - 1;
  controls.rotateSpeed = THREE.MathUtils.clamp(d * 0.85, 0.06, 1.0);
  controls.zoomSpeed = THREE.MathUtils.clamp(d * 1.1, 0.25, 1.1);
  hudAlt.textContent = `${Math.round(d * EARTH_RADIUS_KM).toLocaleString()} km`;

  stepFlight(dt);
  controls.update();
  renderer.render(scene, camera);
}

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

animate();
